class Solution472 {
    class Trie {
        var endsHere = false
        val subtries = Array<Trie?>(26) { null }

        fun addWord(word: String, i: Int) {
            if (i >= word.length) {
                endsHere = true
            } else {
                val key = word[i] - 'a'
                var subTrie = subtries[key]
                if (subTrie == null) {
                    subTrie = Trie()
                    subtries[key] = subTrie
                }
                subTrie.addWord(word, i + 1)
            }
        }

        fun inTrie(word: String, index: Int, end: Int): Boolean {
            if (end == index) {
                return endsHere
            }
            return subtries[word[index]- 'a']?.inTrie(word, index + 1, end) ?: false
        }
    }

    val result = mutableListOf<String>()
    val trie = Trie()

    fun findAllConcatenatedWordsInADict(words: Array<String>): List<String> {
        for (word in words) {
            trie.addWord(word, 0)
        }

        for (word in words) {
            if (word.length < 2) {
                continue
            }
            if (checkWord(word, 0, word.length)) {
                result.add(word)
            }
        }

        return result
    }

    fun checkWord(word: String, start: Int, end: Int): Boolean {
        for (i in start + 1 until end) {
            if (trie.inTrie(word, start, i)) {
                if (trie.inTrie(word, i, end)) {
                    return true
                }
                for (j in end - 1 downTo i) {
                    if (trie.inTrie(word, j, end)) {
                        if (trie.inTrie(word, i, j) || checkWord(word, i, j)) {
                            return true
                        }
                    }
                }
            }
        }
        return false
    }
}